import { readdir, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const KEEP_RELEASES = 3;
const KEEP_TEST_RUNS = 3;
const TEST_FAMILIES = [
  /^packaged-firstcut-/,
  /^integration-\d+$/,
  /^stt-real-verification-\d+$/,
  /^frame-pixels-\d+$/,
  /^standalone-studios-\d+$/,
  /^debug-music-profile-\d+$/,
];

function semverParts(name){
  const m=/^editor-(\d+)\.(\d+)\.(\d+)$/.exec(name);
  return m ? m.slice(1).map(Number) : null;
}
function semverCompare(a,b){
  const av=semverParts(a),bv=semverParts(b);
  if(!av&&!bv)return 0;if(!av)return 1;if(!bv)return -1;
  for(let i=0;i<3;i++){if(av[i]!==bv[i])return bv[i]-av[i];}
  return 0;
}
async function dirBytes(dir){
  let total=0;
  for(const entry of await readdir(dir,{withFileTypes:true}).catch(()=>[])){
    const p=path.join(dir,entry.name);
    if(entry.isDirectory()) total+=await dirBytes(p);
    else if(entry.isFile()) total+=(await stat(p).catch(()=>({size:0}))).size;
  }
  return total;
}

async function removeDirs(dirs,dryRun,removed){
  for(const dir of dirs){
    const bytes=await dirBytes(dir);
    removed.push({path:dir,bytes});
    if(!dryRun)await rm(dir,{recursive:true,force:true});
  }
}

export async function cleanupRetention(root=process.cwd(),{dryRun=false}={}){
  const removed=[];
  const releaseDir=path.join(root,'release');
  const releases=(await readdir(releaseDir,{withFileTypes:true}).catch(()=>[]))
    .filter(e=>e.isDirectory()&&semverParts(e.name))
    .map(e=>e.name).sort(semverCompare);
  await removeDirs(releases.slice(KEEP_RELEASES).map(n=>path.join(releaseDir,n)),dryRun,removed);
  const testDir=path.join(root,'test-results');
  const entries=(await readdir(testDir,{withFileTypes:true}).catch(()=>[])).filter(e=>e.isDirectory());
  for(const pattern of TEST_FAMILIES){
    const matches=[];
    for(const e of entries){
      if(!pattern.test(e.name))continue;
      const full=path.join(testDir,e.name),info=await stat(full);
      matches.push({full,mtime:info.mtimeMs});
    }
    matches.sort((a,b)=>b.mtime-a.mtime);
    await removeDirs(matches.slice(KEEP_TEST_RUNS).map(x=>x.full),dryRun,removed);
  }
  const freed=removed.reduce((n,x)=>n+x.bytes,0);
  return{dryRun,keepReleases:KEEP_RELEASES,keepTestRuns:KEEP_TEST_RUNS,removedCount:removed.length,freedBytes:freed,removed};
}

const isMain=process.argv[1]&&path.resolve(process.argv[1])===path.resolve(fileURLToPath(import.meta.url));
if(isMain){
  const result=await cleanupRetention(process.cwd(),{dryRun:process.argv.includes('--dry-run')});
  const gb=(result.freedBytes/1024/1024/1024).toFixed(3);
  console.log(`Retention cleanup ${result.dryRun?'preview':'complete'}: ${result.removedCount} folders, ${gb} GB ${result.dryRun?'eligible':'freed'}.`);
  for(const x of result.removed.slice(0,30))console.log(`- ${path.relative(process.cwd(),x.path)} (${(x.bytes/1024/1024).toFixed(1)} MB)`);
  if(result.removed.length>30)console.log(`... and ${result.removed.length-30} more`);
}

